<script>
    import { each } from "svelte/internal";

    export let type = "number";
    export let id;
    export let row;
    export let dataCharts;
    export let dataText;

    $: key = row.measure;
    // $: console.log("row", row);
    // $: console.log("key", key);
    // console.log("dataCharts", dataCharts);

    $: thisChart = dataCharts.map((e) => e[key]).filter((e) => e);
    //   let max = row.yaxisend;
    //   let min = row.yaxisstart;
    //   let range = max - min;

    // console.log(thisChart, row.enddate);

    let chartWidth = 300,
        height = 110;
    let el;
</script>

<div class="graphic" {id} bind:this={el} bind:clientWidth={chartWidth}>
    <!-- Chart heading text -->
    <div class="chartContainer">
        <p class="headingText">{row.headingtext}</p>
    </div>

    <svg class="chartDrawing" width="281">
        <!-- This bit draws the chart background -->
        <rect
            class="chartBackground"
            x="35"
            width={chartWidth - 104}
            height="110"
        ></rect>

        <!-- Big number and end date-->
        <text class="bigNo" x={chartWidth / 2 - 12} y={height / 2 + 6}
            >{(Math.round(thisChart * 10) / 10).toFixed(1)}
            {row.directLabelUnit?.includes("%")
                ? row.directLabelUnit
                : " " + row.directLabelUnit}</text
        >
        <text
            class="bigDate"
            x={chartWidth / 2 - 12}
            y={height / 0.95}
            font-size={chartWidth < 290 ? "20px" : "22px"}
            >{row.enddate
                .replace("Sep-", "Sept ")
                .replace("Jun-", "June ")
                .replace("Jul-", "July ")
                .replace("-", " ")}</text
        >
    </svg>
    <p class="updated">Updated: {row.update}</p>
</div>
