<script>
	import { csvParse, autoType } from "d3-dsv";
	import LineChart from "./LineChart.svelte";
	import DualLineChart from "./DualLineChart.svelte";
	import ColumnChart from "./ColumnChart.svelte";
	import StaticNumber from "./StaticNumber.svelte";
	import Glossary from "./Glossary.svelte";
	import topics from "./topics.js";
	import outlooks from "./outlook.js";
	import { onMount } from "svelte";
	import url from "./url";
	import order from "./order";

	export let glossary

	$: glossarySelected = $url.hash.replace("#", "");

	let chartWidth;
	let checkedTopics = topics.map(() => true);
	$: selectedTopics = topics.filter((t, i) => checkedTopics[i]);
	let selected = outlooks[0];

	let lastGlossaryClick = "";

	export let dataCharts, dataText;

	//this makes sure that the tiles are in the right order
	dataText.sort(
		(a, b) => order.indexOf(a.measure) - order.indexOf(b.measure),
	);

	// Inject "i" buttons
	function spliceSlice(str, index, count, add) {
		if (index < 0) {
			index = str.length + index;
			if (index < 0) {
				index = 0;
			}
		}
		return str.slice(0, index) + (add || "") + str.slice(index + count);
	}

	function updateLastGlossaryClick(i) {
		lastGlossaryClick = i;
		console.log(lastGlossaryClick)
	}

	onMount(() => window.updateLastGlossaryClick = updateLastGlossaryClick)

	let count = 0;

	dataText.forEach((e, i) =>
		Object.keys(e).forEach((el) => {
			if(typeof dataText[i][el] == "string"){

				count++

				dataText[i][el]=dataText[i][el].replace(/(?<=\[).+?(?=\])/g, 
				str => {
					let href=str.match(/(?<=\().+?(?=\))/)
					let readable=str.replace(href,"").replace("(","").replace(")","")
					let html=`<a class="i" id="${"gloslink" + count}" onclick="updateLastGlossaryClick('${"gloslink" + count}')" href="#${href}">${readable}</a>`
					return html
				})
				.replace(/\[/g,"")
				.replace(/\]/g,"")


			}
			}))

	function toggleAll(e) {
		selectedTopics = e.target.checked ? [...topics] : [];
	}
</script>

<div id="preText">
	<t>
		We assign each measure an <a class="i" href="#improvelabel" on:click={() => updateLastGlossaryClick("preText")}>improvement</a>,
		<a class="i" href="#declinelabel" on:click={() => updateLastGlossaryClick("preText")}>decline</a>,
		<a class="i" href="#nochange" on:click={() => updateLastGlossaryClick("preText")}>no change</a>, or
		<a class="i" href="#notassessed" on:click={() => updateLastGlossaryClick("preText")}>change not assessed</a> label based on assessment
		of change. See our <a class="i" href="#container" on:click={() => updateLastGlossaryClick("preText")}>definitions tool</a> for definitions of these labels and other
		terms that may be unfamiliar.
	</t>
</div>

<div id="filteringOptions">
	<div id="selectionChange">
		{#each outlooks as value}
			<label class="filterContainer">
				<input
					name="outlooks"
					type="radio"
					{value}
					bind:group={selected}
					tabindex="0"
				/>
				<span class="checkmarkRadio"></span>
				<t class="checkBoxText">{@html value.title}</t>
			</label>
		{/each}
	</div>

	<div id="selectionTopic">
		<label class="filterContainer">
			<input
				type="checkbox"
				on:change={toggleAll}
				checked={selectedTopics.length === topics.length}
				tabindex="0"
			/>
			<span class="checkmarkBox"></span>
			<t class="checkBoxText">Select all</t>
		</label>
		{#each topics as topic}
			<label class="filterContainer">
				<input
					type="checkbox"
					bind:group={selectedTopics}
					value={topic}
					name={topic}
					tabindex="0"
				/>
				<span class="checkmarkBox"></span>
				<t class="checkBoxText">{@html topic.title}</t>
			</label>
		{/each}
	</div>
</div>

{#each selectedTopics as topic}
	<div
		id="wellbeing-head"
		class="topic wellbeingdomain alldomain wellbeing-head all-head Nochange"
		tabindex="-1"
	>
		<hr class="topline {topic.id} head divider" />
		<div class="topTextbox">
			<img
				alt=""
				src="https://www.ons.gov.uk/visualisations/dvcwellbeing/icons/{topic.id}.svg"
			/>
			<div class="innerTextbox">
				<t class="domainHeading">{@html topic.title}</t>
				<p class="domainExplainerText">{@html topic.description}</p>
			</div>
		</div>
	</div>
	{#each dataText.filter((d) => d.topic === topic.id && (selected.id === d.outlook || selected.id === d.outlook2 || selected.id === "allMeasures")) as row}
		<hr class="{topic.id} dividerThin" />
		<div aria-live="assertive" id="tileshere" tabindex="-1">
			<div aria-hidden="true" id="top">
				<div aria-hidden="true" id="secondLayer" class="layer layer0">
					<div id="tile" class="tile tile0">
						<div class="containerTop containerTop0">
							<div class="BgColour">
								<div class="measure {row.topic}">
									{@html row.measuretitle}
								</div>
							</div>
							<div class="change">
								{#if row.outlook2 && row.outlook2 !== "Change not assessed"}
									<p class={"percent " + row.measure + "1"}>
										{row.measure == "unpaidWork"
											? "M:"
											: "L:"}
									</p>
									<p class="outlook {row.outlook}">
										{@html row.outlook}
									</p>
									<p class={"percent " + row.measure + "2"}>
										{row.measure == "unpaidWork"
											? "F:"
											: "S:"}
									</p>
									<p class="outlook {row.outlook2}">
										{@html row.outlook2}
									</p>
								{:else}
									<p class="outlook {row.outlook}">
										{@html row.outlook}
									</p>
								{/if}
							</div>
						</div>
						{#if row.since}
							<div class="since">Since: {row.since}</div>
						{/if}
						<div class="title">{@html row.title}</div>
						<div class="commentary">{@html row.commstext}</div>
						<div class="source">
							Source: <a href={row.sourceURL} target="_blank">
								{@html row.sourcetext}</a
							>
						</div>
					</div>
					<div aria-hidden="true" class="chart chart0">
						{#if row.type == "line"}
							<LineChart
								id="{row.measure}_chart"
								{row}
								{dataCharts}
								type="line"
							/>
						{/if}
						{#if row.type == "dualLine"}
							<DualLineChart
								id="{row.measure}_chart"
								{row}
								{dataCharts}
								type="dualLine"
							/>
						{/if}
						{#if row.type == "number"}
							<StaticNumber
								id="{row.measure}_chart"
								{row}
								{dataCharts}
								{dataText}
								type="number"
							/>
						{/if}
						{#if row.type == "bar"}
							<ColumnChart
								id="{row.measure}_chart"
								{row}
								{dataCharts}
								{dataText}
								type="bar"
							/>
						{/if}
					</div>
					<div class="source2">
						Source: <a href={row.sourceURL} target="_blank">
							{@html row.sourcetext}</a
						>
					</div>
				</div>
			</div>
		</div>
	{/each}
	<div class="backToTop">
		<a href="#filteringOptions">&#x25B2; Back to the top</a>
	</div>
{/each}
{#each glossary as entry, i}
	<p style="visibility:hidden; height:0" id={entry.hash}>{glossary.label}</p>
{/each}

<Glossary {glossarySelected} {glossary} {lastGlossaryClick}/>

<style>
	.topline {
		margin-bottom: 5px;
	}

	a:visited {
		color: rgb(0, 100, 200);
	}
</style>
