<script>
	import { each } from "svelte/internal";
	import { format } from "d3-format";

	export let type = "line";
	export let id;
	export let row;
	export let dataCharts;

	$: key = row.measure;

	$: thisChart = dataCharts.map((e) => e[key]).filter((e) => e);
	$: max = row.yaxisend;
	$: min = row.yaxisstart;
	$: range = max - min;

	let chartWidth = 300,
		height = 110,
		offset = 35,
		rightPosition = 74;

	//Manually setting the margins where needed
	let offsets = [
		["satisRship", 50],
		["depressionAnxiety", 50],
		["sportsPart", 50],
		["crime", 50],
		["diffFinance", 50],
		["genderPaygap", 50],
		["hholdIncome", 55],
		["hholdWealth", 65],
		["incomeInequal", 50],
		["lowIncome", 50],
		["noQuals", 50],
		["unemployment", 50],
	];

	let rightPositions = [
		["genderPaygap", 80],
		["hholdWealth", 90],
		["hholdIncome", 80],
		["greenhouseGas", 85],
	];

	$: {
		offsets.forEach((d) => {
			d[0] == key ? (offset = d[1]) : (offset = offset);
		});

		rightPositions.forEach((d) => {
			d[0] == key
				? (rightPosition = d[1])
				: (rightPosition = rightPosition);
		});
	}

	$: width = chartWidth - offset - rightPosition;

	let el;

	$: textLabel = key == "humanCapital" ? "£" + (Math.round(thisChart[thisChart.length - 1] * 100) / 100).toFixed(2) + " " + row.directLabelUnit 
		: row.directLabelUnit?.includes("%")
		? (Math.round(thisChart[thisChart.length - 1] * 10) / 10).toFixed(1) + row.directLabelUnit //Final value plus the unit
		: row.directLabelUnit //Checking whether there is a directLabelUnit, else display just the value
			? (Math.round(thisChart[thisChart.length - 1] * 10) / 10).toFixed(1) + " " + row.directLabelUnit
			: key == "hholdIncome" || key == "hholdWealth"
				? "£" + format(",.0f")(thisChart[thisChart.length - 1]) //Special formatting for currency
				: thisChart[thisChart.length - 1];
</script>

<div class="graphic" {id} bind:this={el} bind:clientWidth={chartWidth}>
	<!-- Chart heading text -->
	<div class="chartContainer">
		<p class="headingText">{@html row.headingtext}</p>
	</div>

	<svg class="chartDrawing" width="281">
		<!-- This bit draws the chart background -->
		<rect class="chartBackground" x={offset} {width} {height}></rect>
		<!-- Y-axis -->
		<line
			x1={offset}
			x2={offset}
			y1="0"
			y2={height}
			stroke="black"
			stroke-width="0.5px"
		/>
		<line x1={offset - 5} x2={offset} y1="0" y2="0" stroke="grey" />
		<line
			x1={offset - 5}
			x2={offset}
			y1={height}
			y2={height}
			stroke="grey"
		/>
		<text
			x={offset - 5}
			y="0"
			fill="black"
			text-anchor="end"
			dominant-baseline="middle">{format(",.0f")(row.yaxisend)}</text
		>
		<text
			x={offset - 5}
			y={height}
			fill="black"
			text-anchor="end"
			dominant-baseline="middle">{format(",.0f")(row.yaxisstart)}</text
		>

		<!-- X-axis -->
		<!-- X-axis line (if desired)-->
		{#if !row.yaxisstart}
			<line
				x1={offset}
				x2={offset + width}
				y1={height}
				y2={height}
				stroke="lightgrey"
				stroke-width="3px"
			/>
		{/if}

		<line
			x1={offset + width}
			x2={offset + width}
			y1={height}
			y2="115"
			stroke="grey"
		/>
		<line x1={offset} x2={offset} y1={height} y2="115" stroke="grey" />
		<text
			class="startDate"
			x={offset}
			y={height}
			dy="1.5em"
			dominant-baseline="top">{row.startdate}</text
		>
		<text
			class="endDate"
			x={offset + width}
			y={height}
			dy="1.5em"
			dominant-baseline="top">{row.enddate}</text
		>

		<!-- Blue data line-->
		{#each thisChart as point, i}
			<!-- Don't draw lines for missing values -->
			{#if +thisChart[i - 1] && +thisChart[i]}
				<line
					x1={(i - 1) * (width / (thisChart.length - 1)) + offset}
					x2={i * (width / (thisChart.length - 1)) + offset}
					y1={height - ((thisChart[i - 1] - min) / range) * height}
					y2={height - ((thisChart[i] - min) / range) * height}
					stroke="rgb(32, 96, 149)"
					stroke-width="2.5px"
					stroke-linecap="round"
				/>
				<!-- Add a grey band for missing values -->
			{:else if i !== 0}
				<rect
					x={(i - 1) * (width / (thisChart.length - 1)) + offset}
					y={0}
					width={width / (thisChart.length - 1)}
					{height}
					fill="rgba(0,0,0,0.1)"
				/>
			{/if}
		{/each}

		<!--dot and text label-->
		<circle
			cx={offset + width}
			cy={height -
				((thisChart[thisChart.length - 1] - min) / range) * height}
			r="3"
			fill="#206095"
		></circle>
		{#each textLabel.split(" ") as word, i}
			<text
				class="endText"
				x={offset + width - 10}
				y={height -
					((thisChart[thisChart.length - 1] - min) / range) * height}
				dy={14 * (i - (textLabel.split(" ").length - 1) / 2)}
				fill="rgb(51, 51, 51)"
				text-anchor="start"
				dx="1em"
				dominant-baseline="middle"
				font-weight= {i !== 0 ? 400 : 700}>{word}</text
			>
		{/each}
	</svg>
	<p class="updated">Updated: {row.update}</p>
</div>
